<?php require_once __DIR__.'/../config/auth.php';require_role('kasir');$s=db()->prepare("SELECT t.*,u.name cashier,p.method,p.amount,p.change_amount FROM transactions t JOIN users u ON u.id=t.cashier_id JOIN payments p ON p.transaction_id=t.id WHERE t.invoice=? AND t.cashier_id=?");$s->execute([$_GET['id']??'',user()['id']]);$t=$s->fetch();if(!$t)exit('Tidak ditemukan');$d=db()->prepare('SELECT * FROM transaction_details WHERE transaction_id=?');$d->execute([$t['id']]);?><!doctype html><html><head><meta charset="utf-8"><title><?=e($t['invoice'])?></title><style>body{font:12px monospace;width:280px;margin:20px auto;color:#111}h2,p{text-align:center;margin:4px}hr{border:0;border-top:1px dashed}.row{display:flex;justify-content:space-between;margin:6px 0}.total{font-weight:bold;font-size:14px}.no-print{text-align:center;margin:20px}@media print{.no-print{display:none}body{margin:0}}</style></head><body><h2>WARKOP DJOERAGAN</h2><p><?=e($t['invoice'])?></p><p><?=date('d/m/Y H:i',strtotime($t['created_at']))?> · <?=e($t['cashier'])?></p><hr><?php foreach($d as $i):?><div><?=$i['quantity']?>x <?=e($i['product_name'])?></div><div class="row"><span><?=rupiah($i['price'])?></span><span><?=rupiah($i['subtotal'])?></span></div><?php endforeach;?><hr><div class="row"><span>Subtotal</span><span><?=rupiah($t['subtotal'])?></span></div><div class="row"><span>Diskon</span><span><?=rupiah($t['discount'])?></span></div><div class="row total"><span>TOTAL</span><span><?=rupiah($t['total'])?></span></div><div class="row"><span><?=ucfirst($t['method'])?></span><span><?=rupiah($t['amount'])?></span></div><div class="row"><span>Kembali</span><span><?=rupiah($t['change_amount'])?></span></div><hr><p>Terima kasih sudah mampir!</p><div class="no-print"><button onclick="print()">Cetak</button></div></body></html>

